// 本家はタブを全部閉じると、編集面に**入口の案内だけ**が出る（透かしの一覧）。
// 並び・文言・右の鍵の書き方まで本家に合わせてある。
function emptyEditor(board, playerId, locale) {
  // 流せる面が上に重なるので、案内はそちらにも同じものを入れる。
  const v = view(playerId);
  const bottom = Math.min(v.panel ? panelRow(v) - 1 : ROW_LAST, overlayTop(v) - 1);
  const rows = [
    ["wb.gotoFile", "Ctrl+P", { k: "quickOpen" }],
    ["ed.palette", "Ctrl+Shift+P", { k: "screen", nav: go("palette") }],
    ["wb.openFile", "Ctrl+O", { k: "screen", nav: go("openScript") }],
    ["wb.newFile", "Ctrl+N", { k: "newFile" }],
    ["wb.togglePanel", "Ctrl+`", { k: "panelToggle" }]
  ];
  const top = Math.max(ROW_HEAD + 1, Math.floor((ROW_HEAD + 1 + bottom - rows.length) / 2));
  const lines4 = [];
  for (let i = 0; i < rows.length && top + i <= bottom; i++) {
    const [key, keys, action] = rows[i];
    const label = t(locale, key);
    const pad3 = Math.max(1, W_ED - 12 - visibleLength(label) - keys.length);
    board.put(top + i, COL_ED, ED_W, C.darkGray + "      " + C.gray + label + C.darkGray + " ".repeat(pad3) + keys, action);
    lines4.push(C.darkGray + "      " + C.gray + label + C.darkGray + " ".repeat(pad3) + keys);
  }
  board.putScrollBlock(lines4.join("\n"));
}

