world16.beforeEvents.chatSend.subscribe((ev) => {
  const player = ev.sender;
  const message = ev.message;
  if (isActive(player.id)) {
    ev.cancel = true;
    system16.run(() => {
      const locale = getSettings(player).locale;
      const result = handle2(player, message);
      if (result.closed) {
        player.sendMessage(C.gray + t(locale, "live.closed") + C.reset);
        return;
      }
      if (result.run === "run") {
        guard(navigate(player, go("run", { code: code(player.id) })), player);
      } else if (result.run === "check") {
        guard(navigate(player, go("run", { code: code(player.id), checkOnly: true })), player);
      } else if (result.run === "trace") {
        guard(navigate(player, go("run", { code: code(player.id), trace: true })), player);
      } else if (result.run === "save") {
        guard(navigate(player, go("liveSave")), player);
      }
    });
    return;
  }
  if (!message.startsWith(CHAT_PREFIX)) return;
  ev.cancel = true;
  const raw = message.slice(CHAT_PREFIX.length).trim();
  if (!raw) {
    open3(player, "main");
    return;
  }
  const settings = getSettings(player);
  open3(player, "run", { code: settings.expandEscapes ? expandEscapes(raw) : raw });
});
