// 表に無い言語でも必ず何か返す。註釈の印から 1 行だけ組み立てる。
function starterFor(lang) {
  const id = lang && lang.id ? lang.id : "typescript";
  if (STARTERS[id]) return STARTERS[id];
  const spec = GEN_SPECS[id] || GEN_SPECS[(lang && lang.scanner) || ""] || null;
  const mark = spec && spec.lc && spec.lc.length ? spec.lc[0] : (lang && lang.comment) || "#";
  return mark + " " + ((lang && lang.label) || id) + "\n" + mark + " Hello, world!\n";
}

// その言語の「いちばん短いファイル名」。
function starterName(lang, base) {
  const ext = lang && lang.extensions && lang.extensions.length ? lang.extensions[0] : ".txt";
  return (base || "hello") + ext;
}

// ---- 3. プロジェクト／個人 ------------------------------------------------
// **個人** は、その人のタブにだけ置く（ワールドには残らない）。
// **プロジェクト** は、ワールドの保存領域にも書くので、同じワールドの
// 他の人が「開く」から拾える。名前の頭に proj/ を付けて見分ける。
var PROJECT_PREFIX = "proj/";
function isProjectName(name) {
  return String(name || "").indexOf(PROJECT_PREFIX) === 0;
}
function scopedName(scope, name) {
  return scope === "project" ? PROJECT_PREFIX + String(name).replace(PROJECT_PREFIX, "") : String(name);
}
// ひな形からファイルを作って、その場で開く。
function createStarter(player, scope, lang, base) {
  const id = player.id;
  const name = scopedName(scope, starterName(lang, base));
  const code3 = starterFor(lang);
  const ws = space(id);
  ws.tabs.push(newTab(name, code3));
  ws.active = ws.tabs.length - 1;
  if (scope === "project") {
    try {
      saveScript(name, code3);
    } catch {
    }
  }
  try {
    persist2(id);
  } catch {
  }
  return name;
}

// ---- 4. はじめての人 ------------------------------------------------------
// **はじめてワールドを開いて、はじめて編集面を開いた人**にだけ 1 回。
// 何も無い真っ白な画面ではなく、その言語のいちばん短いファイルを 1 枚置く。
function needsStarter(playerId, settings) {
  if (settings && settings.starterDone) return false;
  try {
    return tabs(playerId).length === 0;
  } catch {
    return false;
  }
}
function placeFirstStarter(player, settings) {
  const lang = LANGUAGES[0];
  try {
    createStarter(player, "personal", lang, "hello");
    saveSettings(player, { ...settings, starterDone: true });
  } catch {
  }
}

// **`'` を文字列の印として扱わない言語。**（上の TICK_CHAR を参照）
// 表そのものは前のほうで作られているので、ここで印だけ後付けする。
var TICK_LANGS = [
  "rust", "ocaml", "fsharp", "sml", "haskell", "elm", "purescript",
  "lisp", "scheme", "racket", "clojure", "erlang", "prolog",
  "verilog", "vhdl", "ada", "gleam", "rescript", "cairo", "move", "zig", "odin"
];
for (const id of TICK_LANGS) {
  if (GEN_SPECS[id]) GEN_SPECS[id].tick = true;
}

// **数える括弧を絞る言語。**実際のコード片で測って、誤検出が出たものだけ。
//   Perl  — 正規表現の中の `[a-z)]` を括弧と数えてしまう
//   シェル — `case a) ... ;; esac` の `)` に開きが無い
// 波括弧（とシェルでは角括弧）の閉じ忘れは、これでも捕まえられる。
var NARROW_PAIRS = {
  perl: { "{": "}" },
  shell: { "{": "}", "[": "]" }
};
for (const [id, pairs] of Object.entries(NARROW_PAIRS)) {
  if (!GEN_SPECS[id]) continue;
  GEN_SPECS[id].pairs = pairs;
  const closers = {};
  for (const [open, close] of Object.entries(pairs)) closers[close] = open;
  GEN_SPECS[id].closers = closers;
}

// Lua の長い括弧（`[==[ ... ]==]`）を使う言語。
for (const id of ["lua"]) {
  if (GEN_SPECS[id]) GEN_SPECS[id].long = true;
}

// ------------------------------------------------------------------
// 起動時に scripts/user_extensions.js を読む。**ここが最後**なのは、
// 足し先（EXTENSIONS / COMMANDS2 / T）が全部そろってからでないと
// 並べられないため。利用者の書き間違いで IDE ごと止めない。
// ------------------------------------------------------------------
try {
  const found = adoptModule(USER_EXTENSION_MODULE, "user_extensions.js");
  if (found.length) console.warn("[tsrepl] user extensions: " + found.map((e) => e.id).join(", "));
} catch (e) {
  noteExtError("user_extensions.js", e && e.message ? e.message : String(e));
}
